mapper.select:
SELECT A_PAGING.BRD_NO, A_PAGING.BRD_TITL_NM, A_PAGING.BRD_CONT, A_PAGING.MBR_CD, A_PAGING.MBR_ID, A_PAGING.BRD_PBLS_DTM, A_PAGING.BRD_VW_CNT, A_PAGING.ADS_ID, A_PAGING.ADS_BRD_NO, A_PAGING.ADS_STATUS_CODE, A_PAGING.ADS_BP, A_PAGING.ADS_PIC, A_PAGING.ADS_PIC_TELNO, A_PAGING.ADS_REQ_PBLS_START_DT, A_PAGING.ADS_REQ_PBLS_END_DT FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.BRD_PBLS_DTM DESC) AS RNUM, B.BRD_NO ,B.BRD_TITL_NM ,B.BRD_CONT ,B.MBR_CD ,M.MBR_ID AS MBR_ID ,B.BRD_PBLS_DTM ,B.BRD_VW_CNT ,A.ADS_ID ,A.BRD_NO AS ADS_BRD_NO ,A.ADS_STATUS_CODE ,A.ADS_BP ,A.ADS_PIC ,A.ADS_PIC_TELNO ,A.ADS_REQ_PBLS_START_DT ,A.ADS_REQ_PBLS_END_DT FROM BOARD B INNER JOIN ADS A ON B.BRD_NO = A.BRD_NO INNER JOIN MEMBER M ON B.MBR_CD = M.MBR_CD WHERE 1=1
AND B.BRD_TITL_NM LIKE '%' || #{detailSearch.searchAdsTitle} || '%'
AND M.MBR_ID LIKE '%' || #{detailSearch.searchAdsWriter} || '%'
AND A.ADS_STATUS_CODE = #{detailSearch.searchAdsStatusCode}
AND A.ADS_BP LIKE '%' || #{detailSearch.searchAdsBp} || '%'
AND A.ADS_PIC LIKE '%' || #{detailSearch.searchAdsPic} || '%'
AND A.ADS_PIC_TELNO LIKE '%' || #{detailSearch.searchAdsPicTelno} || '%'
) A_PAGING WHERE RNUM BETWEEN #{firstRecordIndex} AND #{lastRecordIndex}

mapper.update:
UPDATE ADS
SET
    ADS_STATUS_CODE = #{adsClientVO.adsStatusCode}
    , ADS_REJECT_MESSAGE = #{adsClientVO.adsRejectMessage}
WHERE
    BRD_NO = #{brdNo}
